    for (var i in a) {
        var title = a[i].text();
        var url = a[i].attr("href");
        var size = 0.33;
        title = String(title).replace(/\s/g, "");
        url = baseUrl+String(url).replace(/\d+\/$/, "{{page}}/");
       {
            subResult.push({
                "title": title,
                "url": url,
                "style": {
                    "layout_flexGrow": 1,
